	t.Setenv(logging.FileEnvVar, "")

	closeLog := logging.Open()
	t.Cleanup(closeLog)

	run := runInitIn(t, scratchProject(t))
	require.NoError(t, run.err)

	// Closing first flushes and releases the file, which Windows requires
	// before it can be read.
	closeLog()

